mapper.select:
SELECT p.id, p.title, e.name AS authorName, p.view_count AS viewCount, p.posted_at AS postedAt, p.is_pinned AS pinned, pj.name AS projectName, COUNT(DISTINCT c.id) AS commentCount, COUNT(DISTINCT a.id) AS attachmentCount FROM post p JOIN board b ON b.id = p.board_id JOIN project pj ON pj.id = b.project_id JOIN project_member pm ON pm.project_id = pj.id JOIN employee e ON e.employee_no = p.author_no LEFT JOIN post_comment c ON c.post_id = p.id AND c.deleted_at IS NULL LEFT JOIN post_attachment a ON a.post_id = p.id WHERE pm.employee_no = #{loginEmployeeNo} AND b.type = 'NOTICE' AND b.project_id IS NOT NULL AND (b.deleted_at IS NULL OR pj.status IN ('DONE', 'CANCELED')) AND p.status = 'PUBLISHED' AND p.deleted_at IS NULL
AND pj.id = #{request.projectId}
AND e.name LIKE '%' || #{request.keyword}::text || '%'
AND p.title LIKE '%' || #{request.keyword}::text || '%'
GROUP BY p.id, e.name, pj.name ORDER BY p.is_pinned DESC, p.posted_at DESC LIMIT #{request.size} OFFSET #{request.offset}
